INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'initial', 'adj.', '/ɪˈnɪʃ(ə)l/', '开始的;最初的', 'Our initial plan was to climb the mountain in just three days.', '我们最初的计划是只用三天就登上这座山。', 'What an Adventure', 1, 0, 'senior', 'wordlist', 'required3', 'U5', 'the initial plan', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'thus', 'adv.', '/ðʌs/', '因此;从而;如此', 'The air was very thin, and thus many climbers felt weak.', '空气十分稀薄,因此许多登山者感到虚弱。', 'What an Adventure', 2, 0, 'senior', 'wordlist', 'required3', 'U5', 'thus far', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'zone', 'n.', '/zəʊn/', '地区;地带', 'Above 8,000 metres lies the death zone, where the body cannot last long.', '8000米以上是死亡地带,人体在那里无法久留。', 'What an Adventure', 3, 0, 'senior', 'wordlist', 'required3', 'U5', 'the death zone', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'oxygen', 'n.', '/ˈɒksɪdʒ(ə)n/', '氧气', 'Near the summit there is far less oxygen than at sea level.', '在接近峰顶处,氧气比海平面少得多。', 'What an Adventure', 4, 0, 'senior', 'wordlist', 'required3', 'U5', 'lack of oxygen', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'border', 'n.', '/ˈbɔːdə/', '国界;边界', 'Qomolangma lies on the border between Nepal and China.', '珠穆朗玛峰位于尼泊尔和中国的边界上。', 'What an Adventure', 5, 0, 'senior', 'wordlist', 'required3', 'U5', 'on the border', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'confirm', 'v.', '/kənˈfɜːm/', '证实;证明;确认', 'Two climbers were confirmed to have reached the top in 1953.', '1953年有两名登山者被证实登上了峰顶。', 'What an Adventure', 6, 0, 'senior', 'wordlist', 'required3', 'U5', 'confirm the news', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'crowd', 'n.', '/kraʊd/', '人群;一群人', 'The climbers knew the trip would include crowds, cold and danger.', '登山者知道这趟旅程会有人群、寒冷和危险。', 'What an Adventure', 7, 0, 'senior', 'wordlist', 'required3', 'U5', 'a crowd of', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'sheer', 'adj.', '/ʃɪə/', '纯粹的;十足的;陡峭的', 'What we get from this adventure is just sheer joy.', '我们从这次冒险中得到的纯粹是喜悦。', 'What an Adventure', 8, 0, 'senior', 'wordlist', 'required3', 'U5', 'sheer joy', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'attempt', 'n.', '/əˈtempt/', '努力;尝试', 'Most attempts to climb the peak end in either success or failure.', '大多数登顶尝试的结果不是成功就是失败。', 'What an Adventure', 9, 0, 'senior', 'wordlist', 'required3', 'U5', 'an attempt to', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'failure', 'n.', '/ˈfeɪljə/', '失败;失败的人或事', 'He was not afraid of failure when he set out on the adventure.', '踏上这次冒险时,他并不害怕失败。', 'What an Adventure', 10, 0, 'senior', 'wordlist', 'required3', 'U5', 'success or failure', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'psychologist', 'n.', '/saɪˈkɒlədʒɪst/', '心理学家', 'A psychologist spent years studying people who love taking risks.', '一位心理学家花了数年研究喜欢冒险的人。', 'What an Adventure', 11, 0, 'senior', 'wordlist', 'required3', 'U5', 'a psychologist', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'thrill', 'n.', '/θrɪl/', '惊险;刺激;兴奋', 'These risk-takers live for the thrill of a new adventure.', '这些冒险者为新冒险的刺激而活。', 'What an Adventure', 12, 0, 'senior', 'wordlist', 'required3', 'U5', 'the thrill of', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'port', 'n.', '/pɔːt/', '港;港口', 'It was spring when our ship sailed from port for the last time.', '我们的船最后一次从港口起航时正值春天。', 'What an Adventure', 13, 0, 'senior', 'wordlist', 'required3', 'U5', 'sail from port', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'unaware', 'adj.', '/ˌʌnəˈweə/', '未觉察到的;未意识到的', 'We played cards, happily unaware that a deadly storm was near.', '我们玩着牌,丝毫没意识到致命的风暴正在逼近。', 'What an Adventure', 14, 0, 'senior', 'wordlist', 'required3', 'U5', 'unaware of the danger', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'alcohol', 'n.', '/ˈælkəhɒl/', '酒精;含酒精的饮料', 'Clean the cut with fresh water or alcohol before covering it.', '在包扎前用清水或酒精清洗伤口。', 'What an Adventure', 15, 0, 'senior', 'wordlist', 'required3', 'U5', 'clean with alcohol', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'bandage', 'n.', '/ˈbændɪdʒ/', '绷带', 'Once the wound is dry, cover it with a clean bandage.', '伤口干燥后,用干净的绷带包好。', 'What an Adventure', 16, 0, 'senior', 'wordlist', 'required3', 'U5', 'cover with a bandage', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'thermometer', 'n.', '/θəˈmɒmɪtə/', '体温计;温度计', 'Put a thermometer under the tongue to take the person''s temperature.', '把体温计放在舌下,为伤者量体温。', 'What an Adventure', 17, 0, 'senior', 'wordlist', 'required3', 'U5', 'use a thermometer', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'rubber', 'n.', '/ˈrʌbə/', '橡胶;合成橡胶', 'A first aid kit should include a pair of rubber gloves.', '急救包里应该有一副橡胶手套。', 'What an Adventure', 18, 0, 'senior', 'wordlist', 'required3', 'U5', 'rubber gloves', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'cotton', 'n.', '/ˈkɒtn/', '棉;棉布;棉花', 'Use cotton wool balls to clean the area around the wound.', '用药棉球清洁伤口周围。', 'What an Adventure', 19, 0, 'senior', 'wordlist', 'required3', 'U5', 'cotton wool', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'wool', 'n.', '/wʊl/', '羊毛;毛织物', 'She pressed a piece of cotton wool gently onto the cut.', '她把一块药棉轻轻按在伤口上。', 'What an Adventure', 20, 0, 'senior', 'wordlist', 'required3', 'U5', 'cotton wool', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'guideline', 'n.', '/ˈɡaɪdlaɪn/', '指导方针;指导原则', 'Read the first aid guidelines carefully before any adventure.', '在任何冒险之前,仔细阅读急救指南。', 'What an Adventure', 21, 0, 'senior', 'wordlist', 'required3', 'U5', 'first aid guidelines', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'cloth', 'n.', '/klɒθ/', '布;布料', 'Put pressure on the cut with a clean cloth to stop the bleeding.', '用一块干净的布按压伤口以止血。', 'What an Adventure', 22, 0, 'senior', 'wordlist', 'required3', 'U5', 'a clean cloth', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'bleeding', 'n.', '/ˈbliːdɪŋ/', '流血;失血', 'Once the bleeding has stopped, clean the wound with fresh water.', '止血之后,用清水清洗伤口。', 'What an Adventure', 23, 0, 'senior', 'wordlist', 'required3', 'U5', 'stop the bleeding', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'liquid', 'n.', '/ˈlɪkwɪd/', '液体;液态物', 'Wash an insect bite with some liquid medicine first.', '先用一些液体药物清洗被昆虫叮咬的地方。', 'What an Adventure', 24, 0, 'senior', 'wordlist', 'required3', 'U5', 'liquid medicine', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'injury', 'n.', '/ˈɪndʒəri/', '伤;损害;受伤', 'Learning first aid helps you deal with an injury on a trip.', '学习急救能帮你处理旅途中的受伤。', 'What an Adventure', 25, 0, 'senior', 'wordlist', 'required3', 'U5', 'a serious injury', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'stretch', 'v.', '/stretʃ/', '延伸;绵延;伸展', 'Highway 318 stretches over 5,000 kilometres across China.', '318国道在中国境内绵延超过5000公里。', 'What an Adventure', 26, 0, 'senior', 'wordlist', 'required3', 'U5', 'stretch over', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'servant', 'n.', '/ˈsɜːv(ə)nt/', '仆人;佣人', 'The biologist and his servant joined a ship to find the creature.', '这位生物学家和他的仆人登上一艘船去寻找那个生物。', 'What an Adventure', 27, 0, 'senior', 'wordlist', 'required3', 'U5', 'a loyal servant', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'submarine', 'n.', '/ˈsʌbməriːn/', '潜水艇', 'The strange creature turned out to be a secret submarine.', '那个奇怪的生物原来是一艘秘密潜水艇。', 'What an Adventure', 28, 0, 'senior', 'wordlist', 'required3', 'U5', 'inside the submarine', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'charge', 'n.', '/tʃɑːdʒ/', '主管;负责;掌管', 'They met Captain Nemo, the man in charge of the submarine.', '他们见到了掌管潜水艇的尼摩船长。', 'What an Adventure', 29, 0, 'senior', 'wordlist', 'required3', 'U5', 'in charge', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'captain', 'n.', '/ˈkæptɪn/', '船长;队长', 'The captain told the crew that the ship would sail at dawn.', '船长告诉船员,船将在黎明起航。', 'What an Adventure', 30, 0, 'senior', 'wordlist', 'required3', 'U5', 'the ship''s captain', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'ahead', 'adv.', '/əˈhed/', '在前面;向前', 'Captain Nemo walked ahead, with one of his men behind.', '尼摩船长走在前面,他的一名手下跟在后面。', 'What an Adventure', 31, 0, 'senior', 'wordlist', 'required3', 'U5', 'the journey ahead', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'permit', 'v.', '/pəˈmɪt/', '允许;准许;许可', 'Captain Nemo did not permit his guests to leave the submarine.', '尼摩船长不允许他的客人离开潜水艇。', 'What an Adventure', 32, 0, 'senior', 'wordlist', 'required3', 'U5', 'permit sb to do', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'chapter', 'n.', '/ˈtʃæptə/', '章;章节;时期', 'This adventure is adapted from a chapter of Verne''s famous book.', '这次冒险改编自凡尔纳名著中的一章。', 'What an Adventure', 33, 0, 'senior', 'wordlist', 'required3', 'U5', 'the first chapter', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'relate', 'v.', '/rɪˈleɪt/', '讲述;叙述;使有联系', 'Words were not enough to relate the wonders he had seen.', '言语不足以讲述他所见的奇景。', 'What an Adventure', 34, 0, 'senior', 'wordlist', 'required3', 'U5', 'relate the story', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'helmet', 'n.', '/ˈhelmɪt/', '头盔;钢盔', 'Inside his thick helmet, his head shook like a nut in its shell.', '在厚厚的头盔里,他的头像壳中的坚果一样晃动。', 'What an Adventure', 35, 0, 'senior', 'wordlist', 'required3', 'U5', 'a thick helmet', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'nut', 'n.', '/nʌt/', '坚果;坚果仁', 'His head moved inside the helmet like a nut shaking in its shell.', '他的头在头盔里晃动,像坚果在壳里摇动。', 'What an Adventure', 36, 0, 'senior', 'wordlist', 'required3', 'U5', 'like a nut', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'astonish', 'v.', '/əˈstɒnɪʃ/', '使吃惊;使惊讶', 'The power of the light under the ocean astonished the biologist.', '海底光线的力量令这位生物学家大为惊讶。', 'What an Adventure', 37, 0, 'senior', 'wordlist', 'required3', 'U5', 'astonish sb', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'ray', 'n.', '/reɪ/', '光线;光束', 'The rays of the sun shone easily through the watery mass.', '阳光轻易地穿透了那片水体。', 'What an Adventure', 38, 0, 'senior', 'wordlist', 'required3', 'U5', 'the sun''s rays', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'consume', 'v.', '/kənˈsjuːm/', '消耗;消费;吃光', 'The strong light seemed to consume all the colour around him.', '强烈的光线似乎吞没了他周围所有的颜色。', 'What an Adventure', 39, 0, 'senior', 'wordlist', 'required3', 'U5', 'consume colour', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'distinguish', 'v.', '/dɪˈstɪŋɡwɪʃ/', '看清;辨别;区分', 'He could clearly distinguish objects far away under the sea.', '他能清楚地看清海底远处的物体。', 'What an Adventure', 40, 0, 'senior', 'wordlist', 'required3', 'U5', 'distinguish objects', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'gradually', 'adv.', '/ˈɡrædʒuəli/', '逐渐地;逐步地', 'Beyond that point, the colours gradually disappeared into deep blue.', '在那之外,颜色逐渐消失于深蓝之中。', 'What an Adventure', 41, 0, 'senior', 'wordlist', 'required3', 'U5', 'gradually disappear', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'surround', 'v.', '/səˈraʊnd/', '环绕;围绕;包围', 'The water that surrounded him was almost as clear as air.', '环绕着他的海水几乎和空气一样清澈。', 'What an Adventure', 42, 0, 'senior', 'wordlist', 'required3', 'U5', 'be surrounded by', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'shore', 'n.', '/ʃɔː/', '岸;滨;海滨', 'The sand was even, not wrinkled like that on a flat shore.', '那片沙地平整,不像平坦海岸上的沙子那样起皱。', 'What an Adventure', 43, 0, 'senior', 'wordlist', 'required3', 'U5', 'on the shore', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'intensity', 'n.', '/ɪnˈtensɪti/', '(光、声等的)强度;强烈', 'The bright sand drove away the sunlight with wonderful intensity.', '明亮的沙地以惊人的强度反射着阳光。', 'What an Adventure', 44, 0, 'senior', 'wordlist', 'required3', 'U5', 'with intensity', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'depth', 'n.', '/depθ/', '深;深度;深处', 'At a depth of thirty feet, he could still see as if in daylight.', '在三十英尺深处,他仍能看得如同白昼。', 'What an Adventure', 45, 0, 'senior', 'wordlist', 'required3', 'U5', 'at a depth of', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'broad', 'adj.', '/brɔːd/', '宽的;阔的;广泛的', 'Deep under the ocean, he could see as if in broad daylight.', '在深海之下,他看得仿佛在大白天一样。', 'What an Adventure', 46, 0, 'senior', 'wordlist', 'required3', 'U5', 'in broad daylight', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'beneath', 'prep.', '/bɪˈniːθ/', '在……之下;在……正下方', 'A whole new world lay beneath the surface of the sea.', '海面之下藏着一个崭新的世界。', 'What an Adventure', 47, 0, 'senior', 'wordlist', 'required3', 'U5', 'beneath the surface', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'resident', 'n.', '/ˈrezɪd(ə)nt/', '居民;住户', 'The grey seals are the lovely residents of the Farne Islands.', '灰海豹是法恩群岛可爱的居民。', 'What an Adventure', 48, 0, 'senior', 'wordlist', 'required3', 'U5', 'the island''s residents', NULL, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f3u5.01', '①would do(从过去某点看的将来 / 转述的将来)', 'A2', 10, '外研社版必修第三册 U5 — 主句是过去时(said/knew/promised/believed…)、所说的事在当时还没发生(常带 the next day/one day/soon/never…again 等将来标志)时,从句用 would + 动词原形;此时 will 视角错、一般过去尚未发生都不对。', 1, 'required3', 'U5', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f3u5.02', '②was / were going to do(过去的打算、计划，常未实现)', 'A2', 10, '外研社版必修第三册 U5 — 表示过去某时打算/准备做某事(常用 but… 引出没做成),用 was/were going to + 动词原形;现在的 am/is/are going to 视角错、will 视角错、一般过去(表示已做了)与 but 矛盾,都不对。', 2, 'required3', 'U5', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f3u5.03', '③过去将来在转述句中 · 与一般过去/将来的区分', 'A2', 10, '外研社版必修第三册 U5 — 转述过去的话语/想法时,原来的 will→would、be going to→was/were going to;判断靠过去主句与将来标志:从过去看仍未发生用过去将来,已发生用一般过去,从现在看才用 will。', 3, 'required3', 'U5', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.01'), 'Before the climb, Mallory promised his wife that he ____ home safely.', 'would come', 'will come', 'came', 'comes', 'A', '主句 promised 是过去时,''平安回家''当时还没发生 → 过去将来 would come;will 视角错,一般过去尚未发生。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.01'), 'The captain announced that the ship ____ port at dawn the next day.', 'will leave', 'would leave', 'left', 'leaves', 'B', 'announced 过去 + the next day 将来标志 → would leave。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.01'), 'None of the sailors knew that those days ____ their last together.', 'will be', 'are', 'would be', 'have been', 'C', 'knew 过去、当时并不知道结局 → 从过去看的将来 would be。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.01'), 'The old sailor said that he ____ to the sea again one day.', 'will return', 'returned', 'returns', 'would return', 'D', 'said 过去 + again one day 将来 → would return。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.01'), 'Arnette believed that the mountain ____ his life into focus.', 'would bring', 'will bring', 'brought', 'brings', 'A', 'believed 过去,所信之事指向将来 → would bring。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.01'), 'The psychologist predicted that risk-takers ____ always look for new thrills.', 'will', 'would', 'looked', 'look', 'B', 'predicted 过去 + always(指向将来) → would look。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.01'), 'We were excited because we thought the voyage ____ our lives.', 'will change', 'changed', 'would change', 'changes', 'C', 'thought 过去、改变尚未发生 → would change。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.01'), 'The doctor explained that the injury ____ within a few weeks.', 'will heal', 'healed', 'heals', 'would heal', 'D', 'explained 过去 + within a few weeks 将来 → would heal。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.01'), 'As a boy, Verne dreamed that he ____ one day sail around the world.', 'would', 'will', 'did', 'does', 'A', 'dreamed 过去 + one day 将来 → would sail。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.01'), 'The forecast warned that the temperature ____ below minus sixty.', 'will drop', 'would drop', 'dropped', 'drops', 'B', 'warned 过去、所预警之事尚未发生 → would drop。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.01'), 'Conseil was sure that Captain Nemo ____ never let them leave the submarine.', 'will', 'let', 'would', 'lets', 'C', 'was sure 过去 + never(指向将来) → would let。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.01'), 'Aronnax realised that words ____ never be enough to describe such wonders.', 'will', 'were', 'are', 'would', 'D', 'realised 过去,从过去看的判断 → would be。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.01'), 'The team hoped that the good weather ____ until they reached the top.', 'would hold', 'will hold', 'held', 'holds', 'A', 'hoped 过去、天气能否维持指向将来 → would hold。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.01'), 'Hours earlier, no one imagined that the calm sea ____ soon turn deadly.', 'will', 'would', 'turned', 'turns', 'B', 'imagined 过去 + soon 将来 → would turn。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.01'), 'The instructor told the divers that the seals ____ them among the seaweed.', 'will follow', 'followed', 'would follow', 'follow', 'C', 'told 过去、跟随尚未发生 → would follow。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.01'), 'Mallory wrote that the adventure ____ him nothing but sheer joy.', 'will give', 'gave', 'gives', 'would give', 'D', 'wrote 过去,所写的将来感受 → would give。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.01'), 'The captain felt certain that they ____ on the island for many months.', 'would remain', 'will remain', 'remained', 'remain', 'A', 'felt certain 过去 + for many months(指向将来) → would remain。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.01'), 'Before the expedition, the doctor said low air pressure ____ some climbers sick.', 'will make', 'would make', 'made', 'makes', 'B', 'said 过去、所说之事指向旅途中的将来 → would make。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.01'), 'The young climber was sure this experience ____ him far stronger.', 'will make', 'made', 'would make', 'makes', 'C', 'was sure 过去,从过去看的将来 → would make。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.01'), 'We all believed that help ____ before nightfall.', 'will arrive', 'arrived', 'arrives', 'would arrive', 'D', 'believed 过去 + before nightfall(尚未发生) → would arrive。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.02'), 'I ____ some water, but the storm broke all our barrels.', 'was going to collect', 'am going to collect', 'will collect', 'collected', 'A', '过去的打算且未实现(but…) → was going to collect;现在 am going to/will 视角错,collected 表示已收集到与 but 矛盾。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.02'), 'We ____ the tent, but the wind was far too strong.', 'are going to put up', 'were going to put up', 'will put up', 'put up', 'B', '过去打算 + but 未做成 → were going to put up。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.02'), 'The sailors ____ a fire, but they could not find any dry logs.', 'are going to build', 'will build', 'were going to build', 'built', 'C', '过去打算未实现 → were going to build。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.02'), 'I ____ for food, but I hurt my arm on the rocks.', 'am going to hunt', 'will hunt', 'hunted', 'was going to hunt', 'D', '过去打算 + but 受伤未做 → was going to hunt。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.02'), 'Arnette ____ several other peaks, but bad weather stopped him.', 'was going to climb', 'is going to climb', 'will climb', 'climbed', 'A', '过去的计划被天气打断 → was going to climb。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.02'), 'We ____ home that week, but the captain changed the plan.', 'are going to sail', 'were going to sail', 'will sail', 'sailed', 'B', '过去打算 + but 计划改变 → were going to sail。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.02'), 'Mallory ____ at the camp, but the clear sky tempted him higher.', 'is going to rest', 'will rest', 'was going to rest', 'rested', 'C', '过去打算未实现 → was going to rest。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.02'), 'The divers ____ the shipwreck, but the water was too rough.', 'are going to explore', 'will explore', 'explored', 'were going to explore', 'D', '过去计划被海况打断 → were going to explore。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.02'), 'I ____ a photo of the summit, but my hands were frozen.', 'was going to take', 'am going to take', 'will take', 'took', 'A', '过去打算 + but 未拍成 → was going to take。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.02'), 'They ____ port at dawn, but a thick fog held them back.', 'are going to leave', 'were going to leave', 'will leave', 'left', 'B', '过去打算被大雾阻拦 → were going to leave。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.02'), 'She ____ the expedition, but her injury kept her at home.', 'is going to join', 'will join', 'was going to join', 'joined', 'C', '过去打算未实现 → was going to join。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.02'), 'We ____ the death zone before noon, but the snow slowed us down.', 'are going to cross', 'will cross', 'crossed', 'were going to cross', 'D', '过去计划被大雪打乱 → were going to cross。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.02'), 'The captain ____ to his family, but there was no time before the voyage.', 'was going to write', 'is going to write', 'will write', 'wrote', 'A', '过去打算 + but 没时间 → was going to write。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.02'), 'I ____ halfway, but my friends encouraged me to keep going.', 'am going to give up', 'was going to give up', 'will give up', 'gave up', 'B', '过去念头未付诸行动 → was going to give up。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.02'), 'The team ____ from Chengdu, but three friends got injured first.', 'are going to start', 'will start', 'were going to start', 'started', 'C', '过去计划被打断 → were going to start。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.02'), 'He ____ to the nearest island, but the waves were rising fast.', 'is going to swim', 'will swim', 'swam', 'was going to swim', 'D', '过去打算未实现 → was going to swim。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.02'), 'We ____ on the shore, but the tide came in too quickly.', 'were going to camp', 'are going to camp', 'will camp', 'camped', 'A', '过去打算被潮水打断 → were going to camp。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.02'), 'I ____ the bite with water, but the liquid medicine had run out.', 'am going to cool', 'was going to cool', 'will cool', 'cooled', 'B', '过去打算 + but 药用完没做成 → was going to cool。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.02'), 'The guide ____ us up the south ridge, but a landslide blocked the path.', 'is going to lead', 'will lead', 'was going to lead', 'led', 'C', '过去计划被滑坡打断 → was going to lead。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.02'), 'They ____ the whole journey, but the camera broke on the first day.', 'are going to film', 'will film', 'filmed', 'were going to film', 'D', '过去计划未实现 → were going to film。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.03'), 'The biologist promised that he ____ every wonder he saw the next day.', 'would describe', 'will describe', 'described', 'describes', 'A', '转述过去的承诺、事在 the next day → will→would describe。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.03'), 'Verne wrote that one day machines ____ deep beneath the sea.', 'will travel', 'would travel', 'travelled', 'travel', 'B', '过去主句 + one day 将来,转述将来 → would travel。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.03'), 'Arnette explained that the climb ____ him to look deep inside himself.', 'will force', 'forced', 'would force', 'forces', 'C', 'explained 过去、转述当时所说的将来作用 → would force。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.03'), 'Farley said that ''Type T'' people ____ taking risks all their lives.', 'will keep', 'kept', 'keep', 'would keep', 'D', 'said 过去 + all their lives(指向将来) → would keep。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.03'), 'Before the trip, we agreed that we ____ every difficulty along the way.', 'would share', 'will share', 'shared', 'share', 'A', 'agreed 过去、所约定之事在旅途将来 → would share。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.03'), 'She said she ____ the next expedition to the South Pole.', 'is going to join', 'was going to join', 'will join', 'joined', 'B', '转述过去的打算:be going to→was going to join。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.03'), 'They told us they ____ the strait before the storm arrived.', 'are going to cross', 'will cross', 'were going to cross', 'crossed', 'C', '转述过去的计划 → were going to cross。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.03'), 'He explained that he ____ a book about his undersea adventure.', 'is going to write', 'will write', 'wrote', 'was going to write', 'D', 'explained 过去 + 计划:be going to→was going to write。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.03'), 'The guide reminded us that the thin air ____ us feel weak near the top.', 'would make', 'will make', 'made', 'makes', 'A', 'reminded 过去、所提醒之事指向登顶时 → would make。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.03'), 'Mallory was sure that the mountain ____ him pure joy, not money.', 'will give', 'would give', 'gave', 'gives', 'B', 'was sure 过去,转述从过去看的将来 → would give。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.03'), 'The doctor said the bleeding ____ once we pressed the wound firmly.', 'will stop', 'stopped', 'would stop', 'stops', 'C', 'said 过去、所说结果尚未发生 → would stop。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.03'), 'I knew that the journey ahead ____ both my body and my mind.', 'will test', 'tested', 'tests', 'would test', 'D', 'knew 过去 + ahead(指向将来) → would test。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.03'), 'Tom told me he ____ wreck diving near the Farne Islands.', 'was going to try', 'is going to try', 'will try', 'tried', 'A', '转述过去的打算 → was going to try。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.03'), 'Standing on the deck, none of us guessed those waters ____ our ship apart.', 'will tear', 'would tear', 'tore', 'tear', 'B', 'guessed 过去、当时灾难尚未发生 → would tear。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.03'), 'As a young writer, Verne dreamed that humans ____ the centre of the Earth.', 'will reach', 'reached', 'would reach', 'reach', 'C', 'dreamed 过去,转述对将来的设想 → would reach。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.03'), 'The forecast had warned that the temperature ____ sharply after dark.', 'will fall', 'fell', 'falls', 'would fall', 'D', 'had warned 过去 + after dark(将来) → would fall。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.03'), 'At base camp, we hoped the weather ____ clear until we returned.', 'would stay', 'will stay', 'stayed', 'stays', 'A', 'hoped 过去、天气能否维持指向将来 → would stay。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.03'), 'The old sailor often said that he ____ to the sea before he grew too old.', 'will return', 'would return', 'returned', 'returns', 'B', 'said 过去 + before he grew too old(将来) → would return。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.03'), 'The captain told the crew that they ____ port the following morning.', 'will leave', 'left', 'would leave', 'leave', 'C', '转述过去的话 + the following morning 将来 → would leave。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U5' AND code='f3u5.03'), 'We were told that a rescue team ____ for us as soon as the storm passed.', 'is going to search', 'will search', 'searched', 'was going to search', 'D', '转述过去的安排(be going to→was going to);as soon as 引出将来 → was going to search。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Climbing Qomolangma: Worth the Risks?', 'Each year, hundreds of people pay good money for an experience that they know will bring crowds, discomfort and danger. Many become sick because of the extreme cold and the low air pressure, and a few even lose their lives. Yet, despite all this, by the end of the trip many are already planning to return. For these people, climbing Qomolangma is an experience like no other. The mountain can make some feel weak and others feel powerful. Above eight thousand metres lies the death zone, where there is only about thirty per cent of the oxygen found at sea level, and the human body can last there for just a few days. Most attempts end in clear success or in failure. Still, climbers keep coming. They believe that what waits at the top is worth every risk, every cold night and every painful step along the way.', '议论·登珠峰的危险与回报', 148, '[{"q":"What do climbers know before they pay for the trip?","answer":"A","options":["It will involve hardship and real danger.","It will be cheap and comfortable.","It will take only a few hours.","It will be completely safe."],"explanation":"原文 ''an experience that they know will bring crowds, discomfort and danger'' 的转述。"},{"q":"Why can the body stay in the death zone for only a short time?","answer":"B","options":["Because it is too crowded there.","Because there is far too little oxygen.","Because the climb is too cheap.","Because there is too much snow to walk on."],"explanation":"原文 ''只有约30%的氧气…只能待几天'' 的转述。"},{"q":"What is the climbers'' general attitude towards the risks?","answer":"A","options":["They feel the goal is worth the danger.","They think the danger is not real.","They want the trip to be banned.","They regret ever starting the climb."],"explanation":"末段 ''worth every risk'' 的转述。"}]'::jsonb, '[{"word":"death zone","cn":"死亡地带"},{"word":"air pressure","cn":"气压"},{"word":"attempt","cn":"尝试"}]'::jsonb, 2, 'required3', 'U5', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'The Words of George Mallory', 'George Mallory was a British climber who loved Qomolangma. Writing about the mountain, he once said that what we get from such an adventure is just sheer joy. He believed that people do not live only to eat and make money; instead, they eat and make money so that they can enjoy life. For Mallory, that was what life truly meant. Sadly, he died on the mountain in 1924, and his body would not be found for many years. To this day, no one knows for sure whether he reached the top before the mountain took his life. Years later, the American climber Alan Arnette spoke words much like Mallory''s. He said the climb brought into focus what was most important to him. There are, he added, a thousand reasons to turn around and only one to keep going, and a climber must hold on to that single reason when the body begs to stop.', '记叙·马洛里的名言与命运', 155, '[{"q":"According to Mallory, why do people earn money?","answer":"B","options":["Because money is the goal of life.","Because earning lets them enjoy living.","To stop climbing mountains.","To avoid all kinds of joy."],"explanation":"原文 ''挣钱是为了享受生活'' 的转述。"},{"q":"What is still unknown about Mallory?","answer":"C","options":["Where he was born.","What language he spoke.","Whether he made it to the summit before he died.","How much money he earned."],"explanation":"原文 ''没人确知他丧命前是否登顶'' 的转述。"},{"q":"What did Arnette say a climber must do when it gets hard?","answer":"D","options":["Always turn back at once.","Forget why the climb matters.","Climb only for money and fame.","Hold on to the one reason to keep going."],"explanation":"末段 ''抓住那唯一坚持下去的理由'' 的转述。"}]'::jsonb, '[{"word":"sheer","cn":"纯粹的"},{"word":"bring into focus","cn":"使成为焦点"}]'::jsonb, 2, 'required3', 'U5', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'The ''Type T'' Personality', 'Why are some people willing to take such great risks? Recent studies suggest that the wish to take risks may be part of human nature, and that some of us are far more likely to take risks than others. The psychologist Frank Farley has spent years studying people who jump out of planes, drive fast cars and climb high mountains. He calls these people ''Type T'', with the ''T'' standing for ''thrill''. Interestingly, such people often do not see themselves as risk-takers at all. They tend to say that they are experts, not gamblers; they do not want to die and they do not expect to. Farley''s research also suggests that the wish to seek risks is connected to how much a person expects to gain from the result. In other words, the bigger the possible reward, the more some people are ready to face danger to reach it.', '说明·爱冒险的人格', 149, '[{"q":"What does the ''T'' in ''Type T'' stand for?","answer":"A","options":["The wish for thrill and excitement.","A fear of all danger.","A love of quiet, safe days.","A dislike of sport."],"explanation":"原文 ''the T standing for thrill'' 的转述。"},{"q":"How do ''Type T'' people usually see themselves?","answer":"B","options":["As foolish gamblers.","As experts rather than risk-takers.","As people who hope to die young.","As people who hate adventure."],"explanation":"原文 ''他们自认是专家而非冒险者'' 的转述。"},{"q":"What does Farley link the wish to take risks with?","answer":"C","options":["The colour of a person''s clothes.","The weather on a given day.","How much a person hopes to gain.","How tall a person is."],"explanation":"末段 ''冒险欲与预期收益相关'' 的转述。"}]'::jsonb, '[{"word":"Type T","cn":"T型(追求刺激)人格"},{"word":"thrill","cn":"刺激;惊险"}]'::jsonb, 2, 'required3', 'U5', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'A Trip Along Highway 318', 'Highway 318 stretches over five thousand kilometres and runs from Shanghai all the way to Tibet. It is the longest highway in the country and is sometimes called the most dangerous road as well. Yet, because of its amazing views and wild beauty, many also know it as the ''heavenly road''. Last year, a small group of friends cycled part of it to raise money for children in need. They said they had practised hard for months before they set out. Day after day they climbed steep hills and faced falling rocks, and three of them were hurt before the trip was over. Even so, they never thought of giving up. The views, they said, were the finest they had ever seen, and helping the children made every difficult mile feel worthwhile. When they came home, friends asked them many questions, and they were happy to share the story of their adventure.', '记叙·318国道骑行之旅', 152, '[{"q":"Why did the friends cycle along Highway 318?","answer":"D","options":["To win a famous cycling race.","To sell their bikes at the end.","To open a new shop in Tibet.","To raise funds for needy children."],"explanation":"原文 ''为有需要的孩子筹款'' 的转述。"},{"q":"What happened to the group during the trip?","answer":"A","options":["Three of them got injured.","They all gave up halfway.","They never met any danger.","They lost their way completely."],"explanation":"原文 ''three of them were hurt'' 的转述。"},{"q":"How did the friends feel about the hard journey?","answer":"B","options":["They wished they had stayed at home.","They felt it was worth every difficult mile.","They thought it was a waste of time.","They were sorry they had ever started."],"explanation":"原文 ''助人让每一段艰难都值得'' 的转述。"}]'::jsonb, '[{"word":"stretch","cn":"绵延;延伸"},{"word":"heavenly road","cn":"天路"}]'::jsonb, 2, 'required3', 'U5', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Walking on the Sea Bed', 'Jules Verne was a French writer often called the ''Father of Science Fiction'', because he described inventions years before they were real. In one of his most famous books, a biologist named Aronnax walks on the sea bed inside a thick diving suit. He says that words are simply not enough to relate such wonders. As he walks, he no longer feels the weight of his clothes or his heavy helmet. The light that lights the soil far below the surface astonishes him by its power. The sun''s rays shine through the water so easily that he can clearly distinguish objects far away. Beyond that point, the colours gradually darken into deep blue and then disappear. The water around him, he feels, is almost as clear as air. Walking on the fine, even sand, he is amazed that at such a depth he can still see as if in broad daylight.', '记叙·凡尔纳笔下的海底行走', 151, '[{"q":"Why is Verne called the ''Father of Science Fiction''?","answer":"C","options":["He built the first submarine himself.","He was the first French teacher.","He wrote about inventions before they existed.","He only wrote about real history."],"explanation":"原文 ''在发明成真前数年就描写它们'' 的转述。"},{"q":"How does Aronnax feel about the sights under the sea?","answer":"D","options":["They are dull and ordinary.","They are too dark to see at all.","They are exactly like life on land.","They are wonders that words can hardly describe."],"explanation":"原文 ''言语不足以讲述这些奇景'' 的转述。"},{"q":"What surprises Aronnax most at that depth?","answer":"A","options":["That the deep sea still looks as bright as day to him.","That the water is completely black.","That he cannot move his arms.","That there is no water around him."],"explanation":"末句 ''在那样的深处仍能看得如同白昼'' 的转述。"}]'::jsonb, '[{"word":"relate","cn":"讲述"},{"word":"distinguish","cn":"看清;辨别"}]'::jsonb, 2, 'required3', 'U5', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Undersea Adventure at the Farne Islands', 'Come and explore the magical waters around the Farne Islands, one of England''s finest dive sites. With both shallow and deep-water diving, there is something here for divers of every skill level. On a wreck dive, our instructors take you down to the steamer Somali, a six-thousand-ton ship that sank in 1941 during the war. She rests upright on the sea bed about thirty metres below the waves, and she almost looks ready to set sail once more. If you prefer, you can join a scenic dive and swim with the islands'' loveliest residents: the thousands of grey seals that live here all year. The large adult males may look a little scary, but they are quite harmless. The young seals will delight you with their curiosity as they follow you among the seaweed forests. Each one-day tour includes two dives and a buffet lunch, and runs every day from the first of June to the end of July.', '应用·法恩群岛潜水广告', 159, '[{"q":"What can divers see on the wreck dive?","answer":"B","options":["A modern racing boat.","A ship that sank during the war.","A row of small fishing huts.","A bridge above the water."],"explanation":"原文 ''1941年沉没的蒸汽船 Somali'' 的转述。"},{"q":"What does the advert say about the adult grey seals?","answer":"C","options":["They often attack divers.","They are too shy to be seen.","They look scary but do no harm.","They live there only in winter."],"explanation":"原文 ''体型大看着吓人,其实无害'' 的转述。"},{"q":"What is included in each one-day tour?","answer":"D","options":["Only a short boat ride.","A free diving suit to keep.","A night on the island.","A pair of dives plus a midday meal."],"explanation":"末句 ''含两次潜水和自助午餐'' 的转述。"}]'::jsonb, '[{"word":"wreck dive","cn":"沉船潜水"},{"word":"resident","cn":"居民;住户"}]'::jsonb, 2, 'required3', 'U5', 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U5', 'First Aid Before an Adventure', 'Before you set out on an adventure, it is wise to learn some simple first aid. A good first aid (1)____ should always be packed. If an insect (2)____ becomes hot and red, wash the area with some liquid medicine and try to (3)____ it down. For a bad cut, press on it with a clean (4)____ until the (5)____ stops, and then clean the wound with fresh water or (6)____. If someone breaks an arm, place an ice (7)____ on it to reduce the (8)____, and keep the arm still. In hot weather, watch for heatstroke: take the person to a cool place and use a (9)____ to check the temperature. Knowing what to (10)____ in these moments can keep a small problem from becoming a big one.', 129, 2, '[{"q":"1","answer":"A","options":["kit","song","price","game"],"explanation":"first aid kit 急救包。"},{"q":"2","answer":"B","options":["joke","bite","price","song"],"explanation":"insect bite 昆虫叮咬处。"},{"q":"3","answer":"C","options":["sell","lose","cool","throw"],"explanation":"cool it down 使其降温。"},{"q":"4","answer":"D","options":["noise","price","game","cloth"],"explanation":"a clean cloth 干净的布。"},{"q":"5","answer":"A","options":["bleeding","singing","shopping","reading"],"explanation":"the bleeding stops 止血。"},{"q":"6","answer":"B","options":["music","alcohol","weather","traffic"],"explanation":"water or alcohol 清水或酒精。"},{"q":"7","answer":"C","options":["joke","price","pack","song"],"explanation":"an ice pack 冰袋。"},{"q":"8","answer":"D","options":["price","noise","game","pain"],"explanation":"reduce the pain 减轻疼痛。"},{"q":"9","answer":"A","options":["thermometer","camera","ticket","basket"],"explanation":"use a thermometer 用体温计。"},{"q":"10","answer":"B","options":["sell","do","hide","lose"],"explanation":"what to do 该做什么。"}]'::jsonb, 1, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U5', 'The Captain''s Memoir', 'It was spring, and we were sailing from (1)____. We were excited, and none of us knew that these (2)____ be our final days together. At first the waters were (3)____, and we spent our time fishing and playing cards, happily (4)____ that a great storm was near. The captain later wrote in his (5)____ that the trip (6)____ change all our lives. Hours later, huge waves (7)____ over the ship, breaking it in two and throwing us into the sea. Choking with water, we swam to the nearest (8)____. There we sat on the (9)____, cold and frightened, already making plans to (10)____. None of us would forget that terrible night.', 112, 2, '[{"q":"1","answer":"C","options":["garden","kitchen","port","market"],"explanation":"sail from port 从港口起航。"},{"q":"2","answer":"D","options":["will","shall","might","would"],"explanation":"none of us knew(过去)+ 结局未发生 → 过去将来 would be。"},{"q":"3","answer":"A","options":["calm","angry","hungry","late"],"explanation":"the waters were calm 海面平静。"},{"q":"4","answer":"B","options":["afraid","unaware","proud","sure"],"explanation":"happily unaware 浑然不觉。"},{"q":"5","answer":"C","options":["ticket","basket","diary","garden"],"explanation":"wrote in his diary 写在日记里。"},{"q":"6","answer":"D","options":["will change","changed","changes","would change"],"explanation":"wrote(过去)、改变尚未发生 → would change。"},{"q":"7","answer":"A","options":["rose","fell","slept","sold"],"explanation":"waves rose over the ship 巨浪涌上船。"},{"q":"8","answer":"B","options":["garden","island","office","market"],"explanation":"the nearest island 最近的岛。"},{"q":"9","answer":"C","options":["ceiling","roof","shore","wall"],"explanation":"sat on the shore 坐在岸边。"},{"q":"10","answer":"D","options":["sleep","shop","sing","escape"],"explanation":"plans to escape 逃生的计划。"}]'::jsonb, 2, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U5', 'Getting Ready for the Mountain', 'Climbing a high mountain takes months of (1)____. Long before the trip, climbers train hard to get used to thin air and low (2)____. They study maps and plan each (3)____ along the route, so that they can rest and sleep on the way up. Good gear matters too: a warm coat, strong boots and a thick (4)____ to protect the head. The (5)____ checks the weather every day, because a sudden storm can (6)____ a safe climb into a deadly one. Near the top lies the death (7)____, where the body can only last a few (8)____. Most climbers know that the journey (9)____ both body and mind. Yet, when they finally stand on the (10)____, they feel that every hard day was worth it.', 126, 2, '[{"q":"1","answer":"A","options":["preparation","holiday","breakfast","music"],"explanation":"months of preparation 数月准备。"},{"q":"2","answer":"B","options":["water","oxygen","traffic","money"],"explanation":"low oxygen 低氧。"},{"q":"3","answer":"C","options":["song","price","camp","joke"],"explanation":"plan each camp 规划每个营地。"},{"q":"4","answer":"D","options":["ticket","basket","garden","helmet"],"explanation":"a thick helmet 厚头盔。"},{"q":"5","answer":"A","options":["guide","garden","ticket","river"],"explanation":"the guide checks 向导查看。"},{"q":"6","answer":"B","options":["sell","turn","sing","buy"],"explanation":"turn … into … 把……变成……。"},{"q":"7","answer":"C","options":["song","price","zone","game"],"explanation":"the death zone 死亡地带。"},{"q":"8","answer":"D","options":["songs","prices","games","days"],"explanation":"a few days 几天。"},{"q":"9","answer":"A","options":["would test","will test","tested","tests"],"explanation":"know 此处转述过去判断,旅程考验在将来 → would test。"},{"q":"10","answer":"B","options":["kitchen","summit","market","office"],"explanation":"stand on the summit 站上峰顶。"}]'::jsonb, 3, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U5', 'Into the Cave', 'Last summer I joined a small team to explore a deep (1)____ in the mountains. We each wore a helmet with a bright (2)____, because no sunlight could reach so far below the (3)____. Step by step we climbed down into the (4)____, and the air grew cold and wet. Our guide warned us that the path ahead (5)____ slippery, so we moved slowly and held the rope (6)____. Deep inside, we found a huge room whose walls (7)____ us like a stone castle. The silence there was so complete that it almost (8)____ me. We were going to go even (9)____, but our guide said it was getting late, so we turned back. It was the most (10)____ adventure I had ever had.', 124, 2, '[{"q":"1","answer":"C","options":["garden","kitchen","cave","office"],"explanation":"a deep cave 深洞。"},{"q":"2","answer":"D","options":["price","song","joke","light"],"explanation":"a bright light 明亮的灯。"},{"q":"3","answer":"A","options":["ground","ceiling","roof","cloud"],"explanation":"below the ground 地面之下。"},{"q":"4","answer":"B","options":["sun","dark","sky","wind"],"explanation":"into the dark 进入黑暗。"},{"q":"5","answer":"C","options":["will be","was","would be","is"],"explanation":"warned us(过去)、前路情况尚未到 → would be。"},{"q":"6","answer":"D","options":["loudly","sweetly","kindly","tightly"],"explanation":"held the rope tightly 紧紧抓绳。"},{"q":"7","answer":"A","options":["surrounded","sold","opened","painted"],"explanation":"walls surrounded us 墙壁围着我们。"},{"q":"8","answer":"B","options":["helped","astonished","thanked","invited"],"explanation":"almost astonished me 几乎让我吃惊。"},{"q":"9","answer":"C","options":["higher","lighter","deeper","wider"],"explanation":"go deeper 往更深处。"},{"q":"10","answer":"D","options":["boring","ordinary","quiet","amazing"],"explanation":"the most amazing adventure 最精彩的冒险。"}]'::jsonb, 4, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U5', 'Crossing the Desert', 'Crossing a great desert is one of the hardest (1)____ in the world. By day the sun is so strong that travellers must (2)____ their heads, and by night the air turns surprisingly (3)____. Long ago, traders rode camels across the sand, carrying salt, cloth and (4)____ for many weeks. A camel can go for days without (5)____, which made it the perfect animal for such a (6)____. The travellers followed the stars at night, because there were no roads to (7)____ them. They knew the trip (8)____ dangerous, but the riches waiting at the end were worth the (9)____. Even today, a few brave people still cross the desert to feel the same sense of (10)____ that those early traders once knew.', 123, 2, '[{"q":"1","answer":"A","options":["adventures","holidays","dinners","songs"],"explanation":"the hardest adventures 最艰难的冒险。"},{"q":"2","answer":"B","options":["sell","cover","drop","throw"],"explanation":"cover their heads 遮住头部。"},{"q":"3","answer":"C","options":["warm","sweet","cold","loud"],"explanation":"turns cold 变冷。"},{"q":"4","answer":"D","options":["music","traffic","homework","water"],"explanation":"carrying water 携带饮水。"},{"q":"5","answer":"A","options":["drinking","singing","shopping","reading"],"explanation":"without drinking 不喝水。"},{"q":"6","answer":"B","options":["garden","journey","kitchen","market"],"explanation":"such a journey 这样的旅程。"},{"q":"7","answer":"C","options":["sell","paint","guide","cook"],"explanation":"no roads to guide them 没有路指引。"},{"q":"8","answer":"D","options":["will be","is","has been","would be"],"explanation":"knew(过去)、危险尚在前路 → would be。"},{"q":"9","answer":"A","options":["risk","price","song","game"],"explanation":"worth the risk 值得冒险。"},{"q":"10","answer":"B","options":["traffic","freedom","homework","furniture"],"explanation":"a sense of freedom 自由感。"}]'::jsonb, 5, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U5', 'My First Solo Sail', 'When I was sixteen, I made my first solo sailing trip, and I will never (1)____ it. My father, who was a sailor, told me that the sea (2)____ me more than any school. Before I left, I checked the boat carefully and learned some first (3)____ in case of an injury. The first days were (4)____ and bright, and I sailed happily along the (5)____. Then, one evening, dark clouds began to (6)____, and I could see that a storm (7)____ hit before long. I lowered the sail and held on (8)____ as the waves rose around me. By morning the sea was quiet again, and I felt (9)____ that I had faced my fear alone. That trip taught me that courage (10)____ each time we meet a new challenge.', 131, 2, '[{"q":"1","answer":"C","options":["sell","buy","forget","open"],"explanation":"never forget it 永远忘不了。"},{"q":"2","answer":"D","options":["will teach","taught","teaches","would teach"],"explanation":"told me(过去)、教导发生在将来 → would teach。"},{"q":"3","answer":"A","options":["aid","price","song","joke"],"explanation":"first aid 急救。"},{"q":"4","answer":"B","options":["angry","calm","hungry","late"],"explanation":"calm and bright 平静明朗。"},{"q":"5","answer":"C","options":["ceiling","roof","coast","kitchen"],"explanation":"along the coast 沿海岸。"},{"q":"6","answer":"D","options":["sing","sell","sleep","gather"],"explanation":"clouds gather 乌云聚集。"},{"q":"7","answer":"A","options":["was going to","is going to","will","may"],"explanation":"过去看即将发生的事 → was going to hit;现在 is going to/will 视角错。"},{"q":"8","answer":"B","options":["loudly","tightly","sweetly","slowly"],"explanation":"held on tightly 紧紧抓住。"},{"q":"9","answer":"C","options":["afraid","bored","proud","sorry"],"explanation":"felt proud 感到自豪。"},{"q":"10","answer":"D","options":["sells","sleeps","hides","grows"],"explanation":"courage grows 勇气增长。"}]'::jsonb, 6, 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U5 听力·对话 Planning a Camping Trip', '外研社版必修第三册 U5 · dialogue', 3, 'Lucy: Jack, shall we go camping in the mountains this weekend?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U5 听力·短文 Facts about Qomolangma', '外研社版必修第三册 U5 · passage', 2, 'Qomolangma lies on the border between Nepal and China.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U5 听力·对话 An Interview about a Cycling Trip', '外研社版必修第三册 U5 · dialogue', 3, 'Host: So, Tom, why did you cycle all that way?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U5 听力·短文 Jules Verne, Father of Science Fiction', '外研社版必修第三册 U5 · passage', 2, 'Jules Verne was a French writer who lived in the nineteenth century.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U5 听力·对话 Booking a Diving Tour', '外研社版必修第三册 U5 · dialogue', 3, 'Visitor: Hello, I''d like to book a diving tour for this Saturday.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U5 听力·短文 A Tip for Adventurers', '外研社版必修第三册 U5 · passage', 2, 'Here is a simple tip before you go on any adventure.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (10, 'Write an Adventure Story(写一篇冒险故事)', 'An Adventure I Will Never Forget', '假设你叫李华,英语社团要出一期''My Adventure''专栏。请用英语写一篇约100词的冒险故事,内容包括:① 冒险发生的时间、地点和同伴;② 发生了什么(遇到的困难或惊险一刻);③ 你的感受与收获。要求:用一般过去时叙事,并自然用上过去将来时(如 I knew it would …, We were going to …)。', 'Suppose you are Li Hua. Your English club is making a column called ''My Adventure''. Write a story of about 100 words including: 1) when and where the adventure happened and who you were with; 2) what happened (a difficulty or an exciting moment); 3) how you felt and what you learned. Use the past tense to tell the story, and use the past future (e.g. I knew it would…, We were going to…) where it sounds natural.', '["交代时间/地点/同伴(Last summer, my friends and I …)","讲清发生了什么、惊险或困难的一刻(Suddenly … / We were going to …, but …)","用过去将来表达当时对将来的预期(I knew the trip would …)","结尾写感受与收获(It was scary, but I learned that …)"]'::jsonb, 70, 100, 'Last summer, my friends and I went hiking in the mountains. Before we set out, the guide told us that the weather would change quickly, so we packed warm coats and a first aid kit. At first the path was easy, and we were going to reach the top by noon. Then dark clouds gathered, and I knew a storm was coming. We held on to the rope and climbed down slowly and carefully. When we finally reached the camp, everyone was cold but safe. It was the scariest moment of my life, yet I learned that good planning and courage can carry you through any adventure.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["Before we set out, the guide told us that the weather would change quickly.","At first the path was easy, and we were going to reach the top by noon.","Then dark clouds gathered, and I knew a storm was coming.","I learned that good planning and courage can carry you through any adventure."]'::jsonb, '[{"wrong":"He said the weather will change.","correct":"He said the weather would change.","note":"主句过去时,转述将来用 would,而非 will。"},{"wrong":"We were going to reached the top.","correct":"We were going to reach the top.","note":"be going to 后接动词原形。"},{"wrong":"I knew a storm is coming.","correct":"I knew a storm was coming.","note":"主句 knew 为过去,从句时态相应后移。"}]'::jsonb, '【冒险故事结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (10, 'required3', 'U5', '{"title":"过去将来时(would do / was going to do)速查","intro":"过去将来时表示''从过去某个时间点看将要发生的事''。两种主要形式:would + 动词原形、was/were going to + 动词原形。判断口诀:看主句是不是过去时(said/knew/told…),事情在当时还没发生,就用过去将来;will 是从现在看(视角错),一般过去是已发生(尚未发生时不能用)。","table":{"headers":["形式","用法 / 例句"],"rows":[["would + 原形","从过去看的将来 / 转述将来:He said he would climb Qomolangma."],["was/were going to + 原形","过去的打算、计划(常未实现):I was going to collect water, but the storm came."],["现在将来 will / be going to","从现在看的将来(对照):He says he will climb Qomolangma.(主句现在)"],["转述对应","直接引语 will → would;be going to → was/were going to"]]},"specialRules":[{"rule":"主句过去 + 事情当时未发生 → 用 would / was going to,不用 will","mark":"She knew the trip would be hard.(would √ / will ×)"},{"rule":"was/were going to 常表''本打算但没做成'',后面常跟 but…","mark":"We were going to put up the tent, but the wind was too strong."},{"rule":"be going to 后、would 后都接动词原形","mark":"was going to reach √ / was going to reached ×"},{"rule":"主句 knew/said 为过去,从句其他动词也相应后移","mark":"I knew a storm was coming.(was, 非 is)"}],"why":["would 是 will 的过去式、was/were going to 是 be going to 的过去式;当叙述或转述的立足点在过去时,''将来''自然要用它们的过去形式,这样时态前后才一致。"],"gaokaoPoints":["语法填空/改错高频:主句过去时,空格表将来 → would do 或 was/were going to do,别误填 will。","区分 would do(从过去看的将来)与 was going to do(过去的打算、计划,常未实现)。","转述句中 will→would、be going to→was/were going to 的时态后移。"],"examVsReal":[{"exam":"He said he would come the next day.(考试/书面转述)","real":"He said he''s coming tomorrow.","note":"考试看主句过去用 would;口语转述新鲜消息时也可保留现在时态"},{"exam":"I was going to call you, but I forgot.(考试)","real":"I was gonna call you, but I forgot.","note":"口语里 going to 常读作 gonna,书面仍写 going to"}]}'::jsonb, 'fltrp');
